y = 0 
if x < 0:
    print('Negative') 
elif y < 0:
    print('Y Negative') 
else:
    print('None')

value = 'Python' 
if 'y' in value:
    print('Found') 
elif 'o' in value:
    print('Also Found') 
else:
    print('Not Found')

x = 100 
if x > 100:
    print('Over') 
elif x == 100:
    print('Equal') 
else:
    print('Under')
